SELECT id, user_id, contest_id, remind_before_minutes, channel, status, created_time, updated_time
FROM contest_subscription
WHERE id = #{id}

SELECT id, user_id, contest_id, remind_before_minutes, channel, status, created_time, updated_time
FROM contest_subscription
WHERE user_id = #{userId}
  AND contest_id = #{contestId}
  AND remind_before_minutes = #{remindBeforeMinutes}
  AND status = 1
LIMIT 1

SELECT id, user_id, contest_id, remind_before_minutes, channel, status, created_time, updated_time
FROM contest_subscription
WHERE user_id = #{userId}
  AND contest_id = #{contestId}
  AND remind_before_minutes = #{remindBeforeMinutes}
LIMIT 1
